import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/plugins.md","filePath":"zh-HK/user-guide/settings/plugins.md","lastUpdated":1785993908000}'),n={name:"zh-HK/user-guide/settings/plugins.md"};function o(i,a,p,l,d,h){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>列出所有已安裝的插件，頁面頭部的徽標顯示當前加載的 Plugin SDK 版本——點擊它可以直接打開<a href="./../../dev-guide/">開發手冊</a>，這個版本號正是為了對照手冊開發插件而準備的。</p><p>頁面分成左右兩欄：左邊是已安裝的插件，右邊是選中插件的詳情。兩欄各自獨立捲動，插件列表很長和配置表單很長互不牽扯。</p><p>如果沒有安裝任何插件，頁面會顯示一個空狀態提示。</p><h2 id="插件列表" tabindex="-1">插件列表 <a class="header-anchor" href="#插件列表" aria-label="Permalink to &quot;插件列表&quot;">​</a></h2><p>每個已安裝的插件佔一行，顯示名稱，下方是它的版本號。點擊某一行，右側就會打開該插件。</p><p>列表按&quot;有什麼可操作的&quot;排序：先是有自己配置項的插件，其次是有組件可以關閉的，最後是其餘的；每一檔內部按名稱排列。</p><h2 id="選中的插件" tabindex="-1">選中的插件 <a class="header-anchor" href="#選中的插件" aria-label="Permalink to &quot;選中的插件&quot;">​</a></h2><p>右欄最上方是插件的圖示、名稱和<strong>總體功能簡介</strong>。</p><p>再往下，如果插件暴露了自己的配置項(超出簡單啓用/禁用的範疇)，會出現<strong>詳情</strong>和<strong>配置</strong>兩個標籤頁。沒有任何配置項的插件不會顯示標籤欄——整欄就是它的詳情。</p><h3 id="詳情" tabindex="-1">詳情 <a class="header-anchor" href="#詳情" aria-label="Permalink to &quot;詳情&quot;">​</a></h3><p>該插件註冊的功能組件，按類型分組（搜尋源、動態選單提供者等）。每個可切換的組件都有自己的<strong>啓用/禁用核取方塊</strong>；標記為必要項的組件會顯示一個鎖形圖示，不能關閉。把滑鼠懸停在組件旁邊的 <strong>(!)</strong> 上，可以看到該組件的詳細功能說明。</p><p>當某個分組（或整個插件）有 2 個及以上可切換組件時，標題旁會出現一個<strong>全選/全不選</strong>鏈接，點擊即可一次性切換該範圍內的所有核取方塊，不用逐個手動勾選。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>插件自己的設定項，直接在這裡編輯，不再另開對話方塊。如果插件把設定分成了 2 組及以上，這裡還會有一行屬於它自己的標籤頁，每組一個。</p><p>按下<strong>確定</strong>之前，什麼都不會寫入。離開這個標籤頁——切回詳情，或者選擇另一個插件——會把這些欄位回滾到已保存的值，這樣你放棄掉的修改就不會在之後被誤提交。</p><p>想看插件配置實際長什麼樣、能改什麼(比如改一個觸發關鍵詞)，可以參考<a href="./../instant-answers.html">即時答案與關鍵詞功能</a>。</p>',17)])])}const c=t(n,[["render",o]]);export{g as __pageData,c as default};
